#include <iostream>

class ContaBancaria {
private:
    double saldo = 0;

public:
    void depositar(double valor) {
        if (valor > 0) saldo += valor;
    }
    double getSaldo() const {
        return saldo;
    }
};

int main() {
    ContaBancaria conta;
    conta.depositar(100.0);
    // conta.saldo = -500; // erro de compilação: saldo é private
    std::cout << "Saldo: " << conta.getSaldo() << "\n";
    return 0;
}

