#include <iostream>

class Forma {
public:
    virtual double area() const {
        return 0.0;
    }
    virtual ~Forma() {}
};

class Circulo : public Forma {
public:
    double raio;
    Circulo(double r) : raio(r) {}
    double area() const override {
        return 3.14159 * raio * raio;
    }
};

int main() {
    Forma* forma = new Circulo(5.0);
    std::cout << "Área: " << forma->area() << "\n"; // usa a versão de Circulo
    delete forma;
    return 0;
}

#include <iostream>

struct Ponto {
    double x;
    double y;
};

class Retangulo {
public:
    Retangulo(double largura, double altura) : largura_(largura), altura_(altura) {}
    double area() const { return largura_ * altura_; }
private:
    double largura_;
    double altura_;
};

int main() {
    Ponto p{3.0, 4.0}; // acesso direto: struct é public por padrão
    Retangulo r(5.0, 2.0);
    std::cout << "Ponto: (" << p.x << ", " << p.y << ")\n";
    std::cout << "Área do retângulo: " << r.area() << "\n";
    return 0;
}

#include <iostream>

int somar(int a, int b) {
    return a + b;
}

double somar(double a, double b) {
    return a + b;
}

int somar(int a, int b, int c) {
    return a + b + c;
}

int main() {
    std::cout << somar(2, 3) << "\n";        // versão int
    std::cout << somar(2.5, 3.5) << "\n";    // versão double
    std::cout << somar(1, 2, 3) << "\n";     // versão com 3 parâmetros
    return 0;
}

#include <iostream>

class Vetor2D {
public:
    double x, y;
    Vetor2D(double x, double y) : x(x), y(y) {}

    Vetor2D operator+(const Vetor2D& outro) const {
        return Vetor2D(x + outro.x, y + outro.y);
    }
};

int main() {
    Vetor2D v1(1.0, 2.0);
    Vetor2D v2(3.0, 4.0);
    Vetor2D v3 = v1 + v2; // usa o operator+ sobrecarregado
    std::cout << "Resultado: (" << v3.x << ", " << v3.y << ")\n";
    return 0;
}

