#include <iostream>
#include <string>

class Pessoa {
public:
    Pessoa(std::string nome) : nome_(nome) {}

    std::string getNome() const { // não modifica o objeto
        return nome_;
    }

private:
    std::string nome_;
};

void imprimirSaudacao(const std::string& nome) { // apenas lê, não copia nem modifica
    std::cout << "Olá, " << nome << "!\n";
}

int main() {
    const Pessoa p("Maria");
    imprimirSaudacao(p.getNome());
    return 0;
}

