#include <iostream>
#include <stdexcept>

double dividir(double a, double b) {
    if (b == 0) {
        throw std::runtime_error("divisão por zero não é permitida");
    }
    return a / b;
}

int main() {
    try {
        std::cout << dividir(10, 2) << "\n";
        std::cout << dividir(5, 0) << "\n"; // isso vai lançar uma exceção
    } catch (const std::runtime_error& erro) {
        std::cout << "Erro capturado: " << erro.what() << "\n";
    }
    return 0;
}

#include <iostream>

template <typename T>
T maximo(T a, T b) {
    return (a > b) ? a : b;
}

int main() {
    std::cout << maximo(3, 7) << "\n";       // instancia maximo<int>
    std::cout << maximo(2.5, 1.5) << "\n";   // instancia maximo<double>
    std::cout << maximo('a', 'z') << "\n";   // instancia maximo<char>
    return 0;
}

#include <iostream>
#include <memory>

class Recurso {
public:
    void usar() { std::cout << "Usando o recurso\n"; }
    ~Recurso() { std::cout << "Recurso liberado automaticamente\n"; }
};

int main() {
    std::unique_ptr<Recurso> r1 = std::make_unique<Recurso>();
    r1->usar();

    std::shared_ptr<Recurso> r2 = std::make_shared<Recurso>();
    std::shared_ptr<Recurso> r3 = r2; // r2 e r3 compartilham o mesmo objeto
    std::cout << "Contagem de referências: " << r2.use_count() << "\n";
    return 0; // recursos liberados automaticamente aqui
}

#include <iostream>
